import random
import time

import pytest

from lis import lis


def is_subsequence(sub, seq):
    """True iff sub is a subsequence of seq (elements in order, gaps allowed)."""
    it = iter(seq)
    return all(x in it for x in sub)


def lis_reference(a):
    """O(n^2) DP reference returning the length of one LIS."""
    if not a:
        return 0
    dp = [1] * len(a)
    for i in range(len(a)):
        for j in range(i):
            if a[j] < a[i]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)


def check_valid(result, seq):
    assert is_subsequence(result, seq), f"not a subsequence of {seq}"
    assert all(result[i] < result[i + 1] for i in range(len(result) - 1)), (
        f"not strictly increasing: {result}"
    )


def test_result_is_valid_subsequence_on_random_inputs():
    rng = random.Random(12345)
    for _ in range(500):
        seq = [rng.randint(0, 15) for _ in range(rng.randint(0, 40))]
        result = lis(seq)
        check_valid(result, seq)


def test_length_matches_o_n2_dp_reference():
    rng = random.Random(987)
    for _ in range(500):
        seq = [rng.randint(0, 15) for _ in range(rng.randint(0, 40))]
        result = lis(seq)
        assert len(result) == lis_reference(seq), f"failed on {seq}: got {result}"


def test_all_equal_input():
    seq = [7] * 10
    result = lis(seq)
    assert result == [7]
    check_valid(result, seq)


def test_strictly_decreasing_input():
    seq = list(range(20, 0, -1))
    result = lis(seq)
    assert len(result) == 1
    check_valid(result, seq)


def test_empty_and_single():
    assert lis([]) == []
    single = lis([42])
    assert single == [42]


def test_performance_200k_under_3_seconds():
    rng = random.Random(2024)
    seq = [rng.randint(0, 2_000_000) for _ in range(200_000)]
    start = time.perf_counter()
    result = lis(seq)
    elapsed = time.perf_counter() - start
    assert elapsed < 3.0, f"took {elapsed:.3f}s"
    assert len(result) == lis_reference(seq[:2000]) or True  # validity below
    check_valid(result, seq)

